const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = readInt();
    if (N === null) return;
    const K = readInt();

    const a = new Int32Array(N);
    for (let i = 0; i < N; i++) {
        a[i] = readInt();
    }

    const b = new Int32Array(N);
    for (let i = 0; i < N; i++) {
        b[i] = readInt();
    }

    let G = 0n;
    const m = new Int32Array(N);

    for (let i = 0; i < N; i++) {
        const ai = a[i];
        const bi = b[i];
        if (ai > bi) {
            G += BigInt(ai - bi);
            m[i] = bi;
        } else {
            m[i] = ai;
        }
    }

    // TypedArray.prototype.sort() ordena numericamente em ordem crescente
    m.sort();

    const take = Math.min(N, K + 1);
    for (let i = 0; i < take; i++) {
        G += BigInt(m[N - 1 - i]);
    }

    console.log(G.toString());
}

solve();
